def stable_toposort(graph):
    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep!r}")

    nodes = list(graph.keys())
    done = set()
    result = []

    while len(result) < len(nodes):
        placed = False
        for node in nodes:
            if node in done:
                continue
            if all(dep in done for dep in graph[node]):
                result.append(node)
                done.add(node)
                placed = True
                break
        if not placed:
            raise ValueError("Cycle detected")

    return result
```

