def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_sum = 0

    for item in items:
        partition, row_count = item
        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_sum = 0
            batches.append([item])
        elif current_sum + row_count <= max_rows:
            current_batch.append(item)
            current_sum += row_count
        else:
            batches.append(current_batch)
            current_batch = [item]
            current_sum = row_count

    if current_batch:
        batches.append(current_batch)

    return batches
```

