def merge_payload_ranges(items):
    for start, end, payload in items:
        if start > end:
            raise ValueError(f"Invalid range: start {start} > end {end}")

    groups = {}
    for start, end, payload in items:
        if payload not in groups:
            groups[payload] = []
        groups[payload].append((start, end))

    result = []
    for payload, ranges in groups.items():
        ranges.sort()
        cur_start, cur_end = ranges[0]
        for start, end in ranges[1:]:
            if start <= cur_end:
                cur_end = max(cur_end, end)
            else:
                result.append([cur_start, cur_end, payload])
                cur_start, cur_end = start, end
        result.append([cur_start, cur_end, payload])

    result.sort(key=lambda x: (x[0], x[1]))
    return result
```

